import { useState, useEffect, useContext, useRef } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { FaBars, FaTimes } from "react-icons/fa";

export default function AdminDashboard() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [message, setMessage] = useState("");
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();
  const [selectedElectionVotingOpen, setSelectedElectionVotingOpen] = useState(false);

  // Refs for scrolling
  const votingRef = useRef(null);
  const pendingRef = useRef(null);
  const candidatesRef = useRef(null);
  const resultsRef = useRef(null);
  const reportsRef = useRef(null);

  // ---------------- Error handler ----------------
  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchElections = async () => {
    try {
      const res = await api.get("/admin/elections");
      const sorted = res.data.sort((a, b) => new Date(b.startsAt) - new Date(a.startsAt));
      setElections(sorted);
      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);
        setSelectedElectionVotingOpen(firstElection.votingOpen);
        fetchResults(firstElection.id);
      }
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async (electionId) => {
    try {
      const res = await api.get("/admin/results", { params: { electionId } });
      setResults(res.data.positionResults || {});
      setWinners(res.data.winners || {});
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
      setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveCandidate = async (id) => {
    try {
      await api.post(`/admin/approve-candidate/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }
    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchElections();
    };
    init();
  }, [token]);

  const Card = ({ title, children, innerRef }) => (
    <div ref={innerRef} style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px"
    }}>
      <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
      {children}
    </div>
  );

  const scrollTo = (ref) => {
    if (ref.current) {
      ref.current.scrollIntoView({ behavior: "smooth", block: "start" });
      setMenuOpen(false); // close menu after click
    }
  };

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f4f6f8", fontFamily: "Arial, sans-serif" }}>
      {/* Header */}
      <header style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        background: "#007bff",
        padding: "15px 20px",
        color: "#fff",
        position: "relative"
      }}>
        <h1 style={{ fontSize: "1.5rem", margin: 0 }}>iVote Admin</h1>
        <button
          onClick={() => setMenuOpen(!menuOpen)}
          style={{ fontSize: "1.5rem", background: "transparent", border: "none", color: "#fff", cursor: "pointer" }}
        >
          {menuOpen ? <FaTimes /> : <FaBars />}
        </button>

        <nav style={{
          position: "absolute",
          top: "100%",
          right: 0,
          background: "#fff",
          color: "#333",
          width: "250px",
          transform: menuOpen ? "translateX(0)" : "translateX(100%)",
          transition: "transform 0.3s ease",
          boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
          borderRadius: "0 0 12px 12px",
          zIndex: 100
        }}>
          <ul style={{ listStyle: "none", padding: "10px" }}>
            <li><button onClick={() => scrollTo(votingRef)} style={menuBtnStyle}>Voting Status</button></li>
            <li><button onClick={() => scrollTo(pendingRef)} style={menuBtnStyle}>Pending Users</button></li>
            <li><button onClick={() => scrollTo(candidatesRef)} style={menuBtnStyle}>Candidates</button></li>
            <li><button onClick={() => scrollTo(resultsRef)} style={menuBtnStyle}>Election Results</button></li>
            <li><button onClick={() => scrollTo(reportsRef)} style={menuBtnStyle}>Reports</button></li>
            <li><button onClick={() => { logout(); navigate("/login"); }} style={menuBtnStyleRed}>Logout</button></li>
          </ul>
        </nav>
      </header>

      <main style={{ maxWidth: "1000px", margin: "30px auto", padding: "0 15px" }}>
        <Card title="Voting Status" innerRef={votingRef}>
          <p style={{ fontWeight: "bold", color: votingOpen ? "green" : "red" }}>{votingOpen ? "Open" : "Closed"}</p>
          <button onClick={toggleVoting} style={{ ...btnStyle, backgroundColor: votingOpen ? "#dc3545" : "#28a745" }}>
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </Card>

        <Card title="Pending Voter Registrations" innerRef={pendingRef}>
          {/* Table of pending users (same as before) */}
        </Card>

        <Card title="Candidates" innerRef={candidatesRef}>
          {/* Table of candidates (same as before) */}
        </Card>

        <Card title="Election Results" innerRef={resultsRef}>
          {/* Election results table (same as before) */}
        </Card>

        <Card title="Reports" innerRef={reportsRef}>
          <button onClick={generateReport} style={btnStyle}>Generate Final Report</button>
          {reportHash && <p style={{ marginTop: "10px", fontFamily: "monospace" }}>{reportHash}</p>}
        </Card>
      </main>
    </div>
  );
}

// ---------------- Reusable button styles ----------------
const menuBtnStyle = {
  width: "100%", padding: "10px", borderRadius: "6px", border: "none",
  backgroundColor: "#007bff", color: "#fff", fontWeight: "bold", marginBottom: "10px", cursor: "pointer"
};

const menuBtnStyleRed = { ...menuBtnStyle, backgroundColor: "#dc3545" };
const btnStyle = { ...menuBtnStyle, width: "auto", marginTop: "10px" };
